import { useState } from 'react';
import { Button } from '@jinx-ui/react';

type ContactData = {
  fullName: string;
  email: string;
  phone: string;
};

type AddressData = {
  street: string;
  city: string;
  postalCode: string;
};

export type RegistrationData = ContactData & AddressData;

type StepKey = 'contacts' | 'address' | 'review';

const STEPS: { key: StepKey; label: string }[] = [
  { key: 'contacts', label: 'Контакты' },
  { key: 'address', label: 'Адрес' },
  { key: 'review', label: 'Проверка' },
];

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [contacts, setContacts] = useState<ContactData>({
    fullName: '',
    email: '',
    phone: '',
  });
  const [address, setAddress] = useState<AddressData>({
    street: '',
    city: '',
    postalCode: '',
  });

  const isFirstStep = stepIndex === 0;
  const isLastStep = stepIndex === STEPS.length - 1;

  const goBack = () => {
    if (!isFirstStep) setStepIndex((i) => i - 1);
  };

  const goNext = () => {
    if (!isLastStep) setStepIndex((i) => i + 1);
  };

  const handleSubmit = () => {
    onSubmit({ ...contacts, ...address });
  };

  return (
    <div className="jx-card jx-surface" style={{ padding: 'var(--jx-space-6, 24px)' }}>
      <ol
        className="jx-step-indicator"
        aria-label="Шаги регистрации"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-3, 12px)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
          marginBottom: 'var(--jx-space-6, 24px)',
        }}
      >
        {STEPS.map((step, index) => {
          const isCurrent = index === stepIndex;
          const isCompleted = index < stepIndex;
          return (
            <li
              key={step.key}
              className={[
                'jx-step',
                isCurrent ? 'jx-step--current' : '',
                isCompleted ? 'jx-step--completed' : '',
              ]
                .filter(Boolean)
                .join(' ')}
              aria-current={isCurrent ? 'step' : undefined}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--jx-space-2, 8px)',
                color: isCurrent
                  ? 'var(--jx-color-fg-accent)'
                  : isCompleted
                    ? 'var(--jx-color-fg-muted)'
                    : 'var(--jx-color-fg-subtle)',
              }}
            >
              <span
                className="jx-step__badge"
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 'var(--jx-space-6, 24px)',
                  height: 'var(--jx-space-6, 24px)',
                  borderRadius: 'var(--jx-radius)',
                  border: '1px solid var(--jx-color-border)',
                  background: isCurrent
                    ? 'var(--jx-color-accent)'
                    : 'var(--jx-color-bg-subtle)',
                  color: isCurrent
                    ? 'var(--jx-color-fg-on-accent)'
                    : 'var(--jx-color-fg-muted)',
                  fontSize: 'var(--jx-font-size-sm)',
                }}
              >
                {index + 1}
              </span>
              <span className="jx-step__label">{step.label}</span>
            </li>
          );
        })}
      </ol>

      {stepIndex === 0 && (
        <fieldset
          className="jx-fieldset"
          style={{ border: 'none', padding: 0, margin: 0, display: 'grid', gap: 'var(--jx-space-4, 16px)' }}
        >
          <legend className="jx-text jx-text--heading" style={{ marginBottom: 'var(--jx-space-3, 12px)' }}>
            Контакты
          </legend>
          <label className="jx-field">
            <span className="jx-field__label">Полное имя</span>
            <input
              className="jx-input"
              type="text"
              value={contacts.fullName}
              onChange={(e) => setContacts((c) => ({ ...c, fullName: e.target.value }))}
              placeholder="Иван Иванов"
            />
          </label>
          <label className="jx-field">
            <span className="jx-field__label">Email</span>
            <input
              className="jx-input"
              type="email"
              value={contacts.email}
              onChange={(e) => setContacts((c) => ({ ...c, email: e.target.value }))}
              placeholder="ivan@example.com"
            />
          </label>
          <label className="jx-field">
            <span className="jx-field__label">Телефон</span>
            <input
              className="jx-input"
              type="tel"
              value={contacts.phone}
              onChange={(e) => setContacts((c) => ({ ...c, phone: e.target.value }))}
              placeholder="+7 900 000-00-00"
            />
          </label>
        </fieldset>
      )}

      {stepIndex === 1 && (
        <fieldset
          className="jx-fieldset"
          style={{ border: 'none', padding: 0, margin: 0, display: 'grid', gap: 'var(--jx-space-4, 16px)' }}
        >
          <legend className="jx-text jx-text--heading" style={{ marginBottom: 'var(--jx-space-3, 12px)' }}>
            Адрес
          </legend>
          <label className="jx-field">
            <span className="jx-field__label">Улица и дом</span>
            <input
              className="jx-input"
              type="text"
              value={address.street}
              onChange={(e) => setAddress((a) => ({ ...a, street: e.target.value }))}
              placeholder="ул. Ленина, д. 1"
            />
          </label>
          <label className="jx-field">
            <span className="jx-field__label">Город</span>
            <input
              className="jx-input"
              type="text"
              value={address.city}
              onChange={(e) => setAddress((a) => ({ ...a, city: e.target.value }))}
              placeholder="Москва"
            />
          </label>
          <label className="jx-field">
            <span className="jx-field__label">Почтовый индекс</span>
            <input
              className="jx-input"
              type="text"
              value={address.postalCode}
              onChange={(e) => setAddress((a) => ({ ...a, postalCode: e.target.value }))}
              placeholder="101000"
            />
          </label>
        </fieldset>
      )}

      {stepIndex === 2 && (
        <div style={{ display: 'grid', gap: 'var(--jx-space-4, 16px)' }}>
          <h3 className="jx-text jx-text--heading" style={{ margin: 0 }}>
            Проверка данных
          </h3>
          <dl
            className="jx-summary"
            style={{
              display: 'grid',
              gridTemplateColumns: 'auto 1fr',
              rowGap: 'var(--jx-space-2, 8px)',
              columnGap: 'var(--jx-space-4, 16px)',
              margin: 0,
            }}
          >
            <dt className="jx-text jx-text--muted">Имя</dt>
            <dd style={{ margin: 0 }}>{contacts.fullName || '—'}</dd>
            <dt className="jx-text jx-text--muted">Email</dt>
            <dd style={{ margin: 0 }}>{contacts.email || '—'}</dd>
            <dt className="jx-text jx-text--muted">Телефон</dt>
            <dd style={{ margin: 0 }}>{contacts.phone || '—'}</dd>
            <dt className="jx-text jx-text--muted">Адрес</dt>
            <dd style={{ margin: 0 }}>{address.street || '—'}</dd>
            <dt className="jx-text jx-text--muted">Город</dt>
            <dd style={{ margin: 0 }}>{address.city || '—'}</dd>
            <dt className="jx-text jx-text--muted">Индекс</dt>
            <dd style={{ margin: 0 }}>{address.postalCode || '—'}</dd>
          </dl>
        </div>
      )}

      <div
        className="jx-form-actions"
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginTop: 'var(--jx-space-6, 24px)',
        }}
      >
        <Button variant="secondary" onClick={goBack} disabled={isFirstStep}>
          Назад
        </Button>
        {isLastStep ? (
          <Button variant="primary" onClick={handleSubmit}>
            Отправить
          </Button>
        ) : (
          <Button variant="primary" onClick={goNext}>
            Дальше
          </Button>
        )}
      </div>
    </div>
  );
}

